declare function local:isin-ok($s as xs:string) as xs:boolean {
  matches($s, '^[A-Z]{2}[A-Z0-9]{9}[0-9]$') and (
    let $digits := string-join(for $c in string-to-codepoints(substring($s, 1, 11))
                               return if ($c ge 65) then string($c - 55) else codepoints-to-string($c), '')
    let $rev := reverse(string-to-codepoints($digits) ! (. - 48))
    let $sum := sum(for $i in 1 to count($rev) return
                      if ($i mod 2 = 1) then (let $x := $rev[$i] * 2 return if ($x gt 9) then $x - 9 else $x) else $rev[$i])
    return (10 - $sum mod 10) mod 10 = xs:integer(substring($s, 12, 1)))
};
declare function local:lei-ok($s as xs:string) as xs:boolean {
  matches($s, '^[A-Z0-9]{18}[0-9]{2}$') and
  xs:integer(string-join(for $c in string-to-codepoints($s)
                         return if ($c ge 65) then string($c - 55) else codepoints-to-string($c), '')) mod 97 = 1
};
(: Where a node is: the UniqueID of its position, asset or transaction, else its path :)
declare function local:where($n as node()) as xs:string {
  let $owner := $n/ancestor-or-self::*[UniqueID or TransactionID][1]
  return if ($owner) then local-name($owner) || ' ' || ($owner/UniqueID, $owner/TransactionID)[1]
         else string-join($n/ancestor-or-self::* ! local-name(), '/')
};
declare function local:fund($n as node()) as xs:string {
  let $f := $n/ancestor-or-self::Fund[1]
  return 'Fund ' || ($f/Names/OfficialName, $f/Identifiers/LEI, '?')[1]
};
declare function local:dec($s) as xs:decimal? { if ($s castable as xs:decimal) then xs:decimal($s) else () };
(: The node a portfolio, its weights and values belong to: share class, segment, subfund or fund :)
declare function local:owner-node($n as node()) as element()? {
  $n/ancestor-or-self::*[self::ShareClass or self::Segment or self::Subfund or self::Fund][1]
};
declare function local:owner($n as node()) as xs:string {
  let $o := local:owner-node($n)
  return if (empty($o)) then '?'
         else if ($o/self::Fund) then local:fund($o)
         else (if ($o/self::ShareClass) then 'Share class ' else if ($o/self::Segment) then 'Segment ' else 'Subfund ')
              || ($o/Identifiers/ISIN, $o/Names/OfficialName, $o/Identifiers/LEI, '?')[1]
};
declare function local:owner-ccy($n as node()) as xs:string {
  string((local:owner-node($n)/Currency, $n/ancestor::Fund[1]/Currency)[1])
};

checks.query:
let $c := /FundsXML4/ControlData return (
  if (empty($c)) then local:at(/*, 'ControlData is missing') else (),
  for $p in ('UniqueDocumentID', 'DocumentGenerated', 'ContentDate')
  where exists($c) and empty($c/*[local-name() = $p])
  return local:at($c, 'ControlData/' || $p || ' is missing'),
  if (exists($c) and empty($c/DataSupplier/Name)) then local:at(($c/DataSupplier, $c)[1], 'ControlData/DataSupplier/Name is missing') else ())

for $d in /FundsXML4/ControlData/ContentDate[. castable as xs:date]
where xs:date($d) gt current-date()
return local:at($d, 'ContentDate ' || $d || ' is in the future')

(for $c in //*[local-name() = ('Currency', 'CurrencyBuy', 'CurrencySell', 'PriceCurrency', 'SettlementCurrency')][not(*)]
  [not(matches(normalize-space(.), '^[A-Z]{3}$'))]
  return local:at($c, local:where($c) || ': ' || local-name($c) || ' ' || $c || ' is no ISO 4217 code'),
 for $a in //@ccy[not(matches(., '^[A-Z]{3}$'))]
  return local:at($a, local:where($a) || ': ccy=' || $a || ' is no ISO 4217 code'))

for $ps in //Portfolios[Portfolio/Positions/Position/TotalPercentage], $d in distinct-values($ps/Portfolio/NavDate)
let $sum := sum($ps/Portfolio[NavDate = $d]/Positions/Position/TotalPercentage ! local:dec(.))
where abs($sum - 100) gt 0.5
return local:at(($ps/Portfolio[NavDate = $d])[1], local:owner($ps) || ', ' || $d || ': the position weights add up to ' || $sum || ' %')

for $ps in //Portfolios[Portfolio/Positions/Position], $d in distinct-values($ps/Portfolio/NavDate)
let $ccy := local:owner-ccy($ps)
let $tna := local:dec(($ps/../TotalAssetValues/TotalAssetValue[NavDate = $d]/TotalNetAssetValue/Amount[@ccy = $ccy])[1])
let $sum := sum($ps/Portfolio[NavDate = $d]/Positions/Position/TotalValue/Amount[@ccy = $ccy] ! local:dec(.))
where exists($tna) and $tna ne 0 and abs($sum - $tna) div abs($tna) gt 0.01
return local:at(($ps/Portfolio[NavDate = $d])[1], local:owner($ps) || ', ' || $d || ': positions add up to ' || $sum || ' ' || $ccy || ', the net asset value is ' || $tna || ' ' || $ccy || ' (' || round(($sum - $tna) div $tna * 100, 2) || ' %)')

for $ps in //Positions, $id in distinct-values($ps/Position/UniqueID)
where count($ps/Position[UniqueID = $id]) gt 1
return local:at($ps/Position[UniqueID = $id][2], local:fund($ps) || ': position ' || $id || ' appears ' || count($ps/Position[UniqueID = $id]) || ' times')

let $used := (//Positions/Position/UniqueID, //Transaction/AssetUniqueID, //Earning/AssetUniqueID)
for $a in /FundsXML4/AssetMasterData/Asset[not(UniqueID = $used)]
return local:at($a, 'Asset ' || $a/UniqueID || ' (' || $a/Name || ') is not used by any position, transaction or earning')

for $pos in //Positions/Position[Equity or Bond or ShareClass or Certificate or Warrant]
let $v := local:dec(($pos/TotalValue/Amount)[1])
where exists($v) and $v lt 0
return local:at($pos, 'Position ' || $pos/UniqueID || ' has a negative value: ' || $v)

for $f in //Fund[SingleFund/ShareClasses/ShareClass/TotalAssetValues]
let $ccy := string($f/Currency)
for $tav in $f/FundDynamicData/TotalAssetValues/TotalAssetValue
let $d := $tav/NavDate
let $tna := local:dec(($tav/TotalNetAssetValue/Amount[@ccy = $ccy])[1])
let $classes := $f/SingleFund/ShareClasses/ShareClass/TotalAssetValues/TotalAssetValue[NavDate = $d]/TotalNetAssetValue/Amount[@ccy = $ccy]
let $sum := sum($classes ! local:dec(.))
where exists($tna) and exists($classes) and $tna ne 0 and abs($sum - $tna) div abs($tna) gt 0.005
return local:at($tav, local:fund($f) || ', ' || $d || ': share classes add up to ' || $sum || ' ' || $ccy || ', the fund has ' || $tna || ' ' || $ccy)

for $sc in //ShareClass[Prices/Price and TotalAssetValues/TotalAssetValue]
for $tav in $sc/TotalAssetValues/TotalAssetValue
let $price := $sc/Prices/Price[NavDate = $tav/NavDate][1]
let $p := local:dec(($price/NavPrice)[1])
let $shares := local:dec(($tav/SharesOutstanding)[1])
let $tna := local:dec(($tav/TotalNetAssetValue/Amount[@ccy = $price/PriceCurrency], $tav/TotalNetAssetValue/Amount)[1])
where exists($p) and exists($shares) and exists($tna) and $tna ne 0 and abs($p * $shares - $tna) div abs($tna) gt 0.01
return local:at($tav, 'Share class ' || ($sc/Identifiers/ISIN, $sc/Names/OfficialName)[1] || ', ' || $tav/NavDate || ': ' || $p || ' × ' || $shares || ' = ' || round($p * $shares, 2) || ', the net asset value is ' || $tna)

for $t in //Transaction[ValutaDate castable as xs:date and EntryDate castable as xs:date]
where xs:date($t/ValutaDate) lt xs:date($t/EntryDate)
return local:at($t, 'Transaction ' || $t/TransactionID || ': ValutaDate ' || $t/ValutaDate || ' is before EntryDate ' || $t/EntryDate)

let $content := /FundsXML4/ControlData/ContentDate[. castable as xs:date] ! xs:date(.)
where exists($content)
return for $a in /FundsXML4/AssetMasterData/Asset[AssetDetails/*/MaturityDate castable as xs:date]
       let $m := xs:date(($a/AssetDetails/*/MaturityDate)[1])
       where $m lt $content and $a/UniqueID = //Positions/Position/UniqueID
       return local:at($a, 'Asset ' || $a/UniqueID || ' (' || $a/Name || ') matured on ' || $m || ' but is still held')
